def partition(s):
    """Find all ways to partition string into palindromic segments."""
    result = []
    current = []

    def is_palindrome(s, left, right):
        while left < right:
            if s[left] != s[right]:
                return False
            left += 1
            right -= 1
        return True

    def backtrack(start):
        if start == len(s):
            result.append(current[:])
            return

        for end in range(start, len(s)):
            if is_palindrome(s, start, end):
                current.append(s[start:end+1])
                backtrack(end + 1)
                current.pop()

    backtrack(0)
    return result
